const items = $input.all();
const results = [];
const now = new Date();

for (const item of items) {
  const desc = item.json.description || '';
  const nome = item.json.summary || 'Cliente';

  // Get event start time
  const startStr = item.json.start.dateTime || item.json.start.date;
  if (!startStr) continue;

  const startDate = new Date(startStr);

  // Calculate difference in minutes
  const diffMinutes = (startDate.getTime() - now.getTime()) / (1000 * 60);

  // ONLY send reminder if event is between 90 and 150 minutes from now (1.5h to 2.5h)
  if (diffMinutes < 90 || diffMinutes > 150) continue;

  // Extract phone from description
  const phoneMatch = desc.match(/Tel:\s*([^@\n]+)/);
  const phone = phoneMatch ? phoneMatch[1].trim() : null;

  // Extract service from description
  const serviceMatch = desc.match(/Servico:\s*([^\n]+)/);
  const servico = serviceMatch ? serviceMatch[1].trim() : 'seu atendimento';

  // Format time
  const hora = startDate.toLocaleTimeString('pt-BR', {
    hour: '2-digit', 
    minute: '2-digit', 
    timeZone: 'America/Sao_Paulo'
  });

  if (phone) {
    const mensagem = `Oi, ${nome}! Passando pra lembrar do teu horario agendado aqui com a gente pra *${servico}*. Tudo certo pra logo mais? ??`;

    results.push({
      json: {
        telefone: phone,
        nome: nome,
        servico: servico,
        hora: hora,
        mensagem: mensagem
      }
    });
  }
}

// If no events in the window, return empty to stop the flow
if (results.length === 0) {
  return [];
}

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  const telefone = item.json.telefone;
  const nome = item.json.nome || 'querida';

  // Sorteia qual etapa de mensagem enviar (1-5)
  const etapa = Math.floor(Math.random() * 5) + 1;

  const mensagens = {
    1: [
      `Oi! ?? Faz um tempinho que a gente nao te ve por aqui no salao. Ta tudo bem? Estamos com saudades! ??`,
      `Oii! Passando pra saber como voce ta. Faz tempo que nao aparece por aqui e a gente sente falta, viu? ??`,
      `Oii! Sumiu, moca! ?? Ta tudo bem contigo? A gente tava lembrando de voce aqui no salao ??`
    ],
    2: [
      `Oii, ta passando rapidinho pra te lembrar que a gente ta aqui sempre que precisar. Quando quiser agendar ? so me chamar! ??`,
      `Oi! So queria te lembrar que nosso espaco ta sempre aberto pra voce. Quando bater aquela vontade de se cuidar, ja sabe ne? ??`,
      `Oii! Lembrei de voce hoje e quis mandar um oi. A porta do salao ta sempre aberta pra voce, ta? ??`
    ],
    3: [
      `Sabe aquele dia que voce sai do salao se sentindo incrivel? ?? Ta na hora de se dar esse presente de novo! Bora marcar?`,
      `Oi! Voce merece um dia de cuidado, ne? Quando quiser se mimar um pouquinho, me chama que eu acho o melhor horario pra voce ?????`,
      `Que tal dar uma passadinha aqui no salao? as vezes a gente precisa parar um pouquinho e se cuidar. Ta aqui pra te ajudar a agendar! ??`
    ],
    4: [
      `Nao esquece que voce ? especial pra gente! ?? Quando sentir vontade, ? so chamar que a gente cuida de tudo pra voce.`,
      `Oi! Passando mais uma vez porque a gente realmente sente falta de te atender. Voce ? daquelas clientes que faz nosso dia! ??`,
      `Oii! So quero que saiba que quando quiser voltar, vai ser recebida com todo carinho do mundo. Estamos aqui! ??`
    ],
    5: [
      `Aqui ? eu passando pra dizer que quando voce quiser voltar, a porta ta aberta e a gente te recebe de bracos abertos. Se cuida, ta? ????`,
      `Oi! Vou parar de encher tua paciencia ?? Mas fica sabendo que a hora que quiser voltar, vai ser uma alegria te atender de novo. Beijo! ??`,
      `Prometo que ? a ultima mensagem por enquanto! ?? Mas quero que saiba que voce tem um lugar especial aqui no salao. Ate a proxima, linda! ??`
    ]
  };

  const variantes = mensagens[etapa];
  const mensagem = variantes[Math.floor(Math.random() * variantes.length)];

  // Delay aleatorio entre 30s e 5min
  const delayMs = 30000 + Math.floor(Math.random() * 270000);

  results.push({
    json: { telefone, nome, etapa, mensagem, delayMs }
  });
}

if (results.length === 0) return [];

// Embaralha
for (let i = results.length - 1; i > 0; i--) {
  const j = Math.floor(Math.random() * (i + 1));
  [results[i], results[j]] = [results[j], results[i]];
}

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  const cupom = (item.json.cupom || '').toUpperCase().trim();

  let tipo_usuario = 'comum';
  let dias_teste = 7;

  // Validate coupon
  if (cupom === 'VALIDA3MESES') {
    tipo_usuario = 'parceiro';
    dias_teste = 90;
  } else if (cupom === 'SOCIOVIP') {
    tipo_usuario = 'parceiro';
    dias_teste = 180;
  }

  // Calculate expiration date
  const now = new Date();
  const expiracao = new Date(now.getTime() + (dias_teste * 24 * 60 * 60 * 1000));

  results.push({
    json: {
      ...item.json,
      tipo_usuario,
      dias_teste,
      cupom_aplicado: cupom || null,
      data_expiracao: expiracao.toISOString(),
      data_criacao: now.toISOString(),
    }
  });
}

return results;

