let bufferRaw = null;
try { bufferRaw = $('Buscar Mensagens').first().json.mensagens; } catch (e) { bufferRaw = null; }

let buffer;
try {
  buffer = bufferRaw ? JSON.parse(bufferRaw) : null;
} catch (e) { buffer = null; }

const msg = $('Mensagem').first().json;

if (!buffer || !Array.isArray(buffer.mensagens) || buffer.mensagens.length === 0) {
  // Buffer sumiu (TTL expirou ou nunca foi gravado) -- usa so a mensagem desta execucao.
  buffer = {
    latest: msg.mensagemid,
    perguntou_confirmacao: false,
    mensagens: [{ tipo: 'texto', conteudo: msg.text || '', timestamp: new Date().toISOString() }],
  };
}

const souAMaisRecente = buffer.latest === msg.mensagemid;

if (!souAMaisRecente) {
  return [{ json: { _acao: 'stale', telefone: msg.telefone, instancia: msg.instancia } }];
}

const LIMITE_FOTOS_REFERENCIA = 5;
const fotos = buffer.mensagens.filter(m => m.tipo === 'imagem').length;

if (fotos >= LIMITE_FOTOS_REFERENCIA && !buffer.perguntou_confirmacao) {
  buffer.perguntou_confirmacao = true;
  return [{ json: {
    _acao: 'perguntar_confirmacao',
    telefone: msg.telefone,
    instancia: msg.instancia,
    bufferJson: JSON.stringify(buffer),
  } }];
}

const textoConsolidado = buffer.mensagens
  .map(m => m.tipo === 'texto' ? m.conteudo : ('[' + m.tipo + '] ' + m.conteudo))
  .join('\n');

let pushName = '';
try { pushName = $('Montar Contexto Dinamico').first().json.pushName || ''; } catch (e) {}

return [{ json: {
  _acao: 'consolidar',
  text: textoConsolidado,
  mensagens: textoConsolidado,
  telefone: msg.telefone,
  instancia: msg.instancia,
  pushName: pushName,
} }];

// Decide audio SOMENTE quando cliente pedir
