const msgCliente = ($('Montar Contexto Dinamico').first().json.text || '').toLowerCase();

const pediuAudio = msgCliente.includes('audio') || 
  msgCliente.includes('audio') || 
  msgCliente.includes('voz') ||
  msgCliente.includes('me fala') || 
  msgCliente.includes('manda um audio') ||
  msgCliente.includes('responde em audio') ||
