const txt = v => (v == null || v === '') ? '' : String(v).trim();

let filtroData = {};
try { filtroData = $('Filtro + Extrair').first().json; } catch { filtroData = {}; }

const telefone = txt(filtroData.telefone);
const pushName = txt(filtroData.pushName);
const fromMe = filtroData.fromMe ?? false;
const evento = txt(filtroData.evento);
const instanciaWebhook = txt(filtroData.instance);
const text = txt(filtroData.text);
const messageId = txt(filtroData.messageId);

let rawNegocio = [];
try { rawNegocio = $('Carregar Dados Negocio').all().map(i => i.json); } catch { rawNegocio = []; }

if (rawNegocio.length === 0) {
  return [{ json: { erro: 'Cliente nao encontrado.', instancia_recebida: instanciaWebhook } }];
}

const negocio = rawNegocio[0];
const instanciaFinal = instanciaWebhook || txt(negocio.instancia_whatsapp);

// Parsear servicos e profissionais do JSON salvo no banco
let servicosLista = 'Consultar servicos disponiveis.';
let profissionaisLista = 'Equipe disponivel sob consulta.';
let profsParsed = [];

try {
  const servicosRaw = negocio.servicos_json || '';
  if (servicosRaw && servicosRaw !== '[]' && servicosRaw !== '') {
    let servicos = typeof servicosRaw === 'string' ? JSON.parse(servicosRaw) : servicosRaw;
    if (Array.isArray(servicos) && servicos.length > 0) {
      servicosLista = servicos.map(s => {
        const nome = s.titulo_servico || s.nome || s.nome_servico || 'Servico';
        const preco = s.valor_base || s.preco || s.valor || 'Sob consulta';
        const duracao = s.tempo_estimado_minutos || s.duracao || s.duracao_minutos || s.tempo || '';
        return `- ${nome}: R$ ${preco}${duracao ? ' (' + duracao + ' min)' : ''}`;
      }).join('\n');
    }
  }
} catch(e) {
  // Se nao for JSON valido, usa o texto direto
  if (negocio.servicos_json && negocio.servicos_json.trim() !== '') {
    servicosLista = negocio.servicos_json;
  }
}

try {
  const profRaw = negocio.profissionais_json || '';
  if (profRaw && profRaw !== '[]' && profRaw !== '') {
    let profs = typeof profRaw === 'string' ? JSON.parse(profRaw) : profRaw;
    if (Array.isArray(profs) && profs.length > 0) {
      profsParsed = profs;
