try {

let bufferRaw = null;
try { bufferRaw = $input.first().json.mensagens; } catch (e) { bufferRaw = null; }

let buffer;
try {
  buffer = bufferRaw ? JSON.parse(bufferRaw) : null;
} catch (e) { buffer = null; }
if (!buffer || typeof buffer !== 'object' || !Array.isArray(buffer.mensagens)) {
  buffer = { latest: null, perguntou_confirmacao: false, mensagens: [] };
}

// FIX 2026-07-16: a versao anterior chamava $('Envio de Imagens')/$('Mensagem de Audio')/
// $('Envio de Documentos') -- nodes que so rodam em UM dos 5 branches do Switch por
// execucao. Chamar $(nodeName) para um node sem runData nesta execucao trava o Task
// Runner do n8n (processo externo) em vez de lancar um erro capturavel pelo try/catch --
// resultou em "Task execution timed out after 300 seconds" e, pior, o restart forcado do
// runner derrubou em cascata outras execucoes concorrentes (de qualquer tenant) que
// estavam usando o mesmo processo. Corrigido: le o tipo da mensagem direto do payload
// bruto do Webhook (node que SEMPRE roda, sem ambiguidade), sem referenciar nodes de
// outros branches.
function detectarTipo() {
  let body = {};
  try { body = $('Webhook').first().json.body || {}; } catch (e) { body = {}; }
  const msg = (body.data && body.data.message) || {};
  if (msg.imageMessage) return 'imagem';
  if (msg.audioMessage) return 'audio';
  if (msg.documentMessage) return 'documento';
  return 'texto';
}

const msg = $('Mensagem').first().json;
buffer.mensagens.push({
  tipo: detectarTipo(),
  conteudo: msg.text || '',
  timestamp: new Date().toISOString(),
});
buffer.latest = msg.mensagemid;

return [{ json: {
  instancia: msg.instancia,
  telefone: msg.telefone,
  bufferJson: JSON.stringify(buffer),
} }];

} catch (e) {
  // Falha rapido e explicito em vez de travar: buffer no Redis fica intacto (TTL 300s),
  // a proxima mensagem do cliente retoma o debounce normalmente.
  throw new Error('Montar Buffer Atualizado falhou: ' + e.message);
}

