const items = $input.all();
const results = [];
const now = new Date();

for (const item of items) {
  const desc = item.json.description || '';
  const nome = item.json.summary || 'Cliente';

  // Get event start time
  const startStr = item.json.start.dateTime || item.json.start.date;
  if (!startStr) continue;

  const startDate = new Date(startStr);

  // Calculate difference in minutes
  const diffMinutes = (startDate.getTime() - now.getTime()) / (1000 * 60);

  // ONLY send reminder if event is between 90 and 150 minutes from now (1.5h to 2.5h)
  if (diffMinutes < 90 || diffMinutes > 150) continue;

  // Extract phone from description
  const phoneMatch = desc.match(/Tel:\s*([^@\n]+)/);
  const phone = phoneMatch ? phoneMatch[1].trim() : null;

  // Extract service from description
  const serviceMatch = desc.match(/Servico:\s*([^\n]+)/);
  const servico = serviceMatch ? serviceMatch[1].trim() : 'seu atendimento';

  // Format time
  const hora = startDate.toLocaleTimeString('pt-BR', {
    hour: '2-digit', 
    minute: '2-digit', 
    timeZone: 'America/Sao_Paulo'
  });

  if (phone) {
    const mensagem = `Oi, ${nome}! Passando pra lembrar do teu horario agendado aqui com a gente pra *${servico}*. Tudo certo pra logo mais? ??`;

    results.push({
      json: {
        telefone: phone,
        nome: nome,
        servico: servico,
        hora: hora,
        mensagem: mensagem
      }
    });
  }
}

// If no events in the window, return empty to stop the flow
if (results.length === 0) {
  return [];
}

return results;

const items = $input.all();
const results = [];

for (const item of items) {
