const promoDesconto = $('Extrair Dados Promo').first().json.promo_desconto || '';
const promoServico = $('Extrair Dados Promo').first().json.promo_servico || 'nossos servicos';
const promoValidade = $('Extrair Dados Promo').first().json.promo_validade || '';

for (const item of clientes) {
  const nome = (item.json.nome || 'querida').split(' ')[0];
  const telefone = item.json.telefone;

  // 6 variacoes da mensagem para anti-spam
  const variacoes = [
    `Oi, ${nome}! ?? Tenho uma novidade especial pra voce: ${promoTexto}. ${promoValidade ? 'Valida ' + promoValidade + '.' : ''} Quer aproveitar? Me chama que eu ja agendo pra voce! ??`,
    `${nome}, oi! Passando pra te contar que temos uma promocao incrivel: ${promoTexto}! ${promoValidade ? 'Corre que ? ate ' + promoValidade + '!' : ''} Bora agendar? ??`,
    `Oi ${nome}! ?? Novidade no salao! ${promoTexto}. ${promoValidade ? 'Aproveita que vai so ate ' + promoValidade + '.' : ''} Quer marcar? ? so me chamar!`,
    `${nome}, voce merece se cuidar! ?? E pra facilitar: ${promoTexto}. ${promoValidade ? 'Promocao valida ' + promoValidade + '.' : ''} Vem pro salao?`,
    `Oii ${nome}! Ta com uma oferta especial aqui pra voce: ${promoTexto} ?? ${promoValidade ? 'Mas corre que ? so ' + promoValidade + '!' : ''} Agenda comigo!`,
    `${nome}, boa noticia! ?? ${promoTexto}. ${promoValidade ? 'Vai de ' + promoValidade + '.' : ''} Aproveita e marca teu horario! Me chama aqui ??`,
  ];

  // Escolhe variacao aleatoria
  const mensagem = variacoes[Math.floor(Math.random() * variacoes.length)];

  // Delay aleatorio: entre 45s e 8min entre cada envio
  const delayMs = 45000 + Math.floor(Math.random() * 435000);

  results.push({
    json: {
      telefone,
      nome,
      mensagem,
      delayMs
    }
  });
}

// Embaralha ordem dos clientes (anti-spam extra)
for (let i = results.length - 1; i > 0; i--) {
  const j = Math.floor(Math.random() * (i + 1));
  [results[i], results[j]] = [results[j], results[i]];
}

if (results.length === 0) return [];
return results;

