  // Buffer sumiu (TTL expirou ou nunca foi gravado) -- usa so a mensagem desta execucao.
  buffer = {
    latest: msg.mensagemid,
    perguntou_confirmacao: false,
    mensagens: [{ tipo: 'texto', conteudo: msg.text || '', timestamp: new Date().toISOString() }],
  };
}

