} catch(e) {
  // Se nao for JSON valido, usa o texto direto
  if (negocio.servicos_json && negocio.servicos_json.trim() !== '') {
    servicosLista = negocio.servicos_json;
  }
}

try {
  const profRaw = negocio.profissionais_json || '';
