  // proprio WhatsApp Business tambem tem fromMe=true e pushName preenchido -- identica
  // a uma resposta manual no payload. Isso NAO e um humano assumindo a conversa, entao
  // nao pode ativar a trava (senao a IA fica bloqueada em loop toda vez que a mensagem
  // automatica dispara). Ignorar mensagens que batem com templates conhecidos.
  const autoReplyMarkers = [
    'No momento, posso não conseguir responder imediatamente',
    'envie seu nome e um breve resumo da situação'
  ];
  if (autoReplyMarkers.some(marker => text.includes(marker))) return [];
}

if (!hasContent && !fromMe) return [];

return [{ json: {
  instance: String(instance),
  remoteJid,
  telefone: remoteJid.replace(/@s\.whatsapp\.net$/, ''),
  text,
  pushName,
  fromMe,
