  let acao = 'cliente_falou';

  if (fromMe) {
    const isReactivateCmd = /^#(reativar|retomar|voltar|despausar) /i.test(text);
    const isPauseCmd = /^#(pausar|humano|pause|parar) /i.test(text);
    const isManualNonCommand = !text.startsWith('#');

    if (isReactivateCmd) {
      acao = 'reativar_ia';
    } else if (isPauseCmd) {
      acao = 'humano_falou';
    } else if (isManualNonCommand) {
      if (!travaOwnerAtivada) continue;
      acao = 'humano_falou';
    } else {
      acao = 'comando_proprietario';
    }
  }

  results.push({ json: { ...data, ...flagRow, _acao: acao } });
}

return results;

